fn intersperse(numbers: &[i32], delim: i32) -> Vec<i32> {
    let n = numbers.len();
    
    // Handle empty input
    if n == 0 {
        return Vec::new();
    }
    
    // Pre-allocate with exact capacity: 2n - 1
    let mut result = Vec::with_capacity(2 * n - 1);
    
    // Add first element
    result.push(numbers[0]);
    
    // For remaining elements, add delimiter then element
    for i in 1..n {
        result.push(delim);
        result.push(numbers[i]);
    }
    
    result
}